def get_exact_txt_keyring_geometries():
    """Restituisce le geometrie 2D (base_2d, text_2d, symbol_2d) del portachiavi TXT ENNOVA."""
    b = wkt.loads(WKT_BASE_2D)
    t = wkt.loads(WKT_TEXT_2D)
    s = wkt.loads(WKT_SYM_2D)
    return b, t, s

def get_txt_modular_components():
    """
    Restituisce (sym_fluid, divider_bar, letters):
    - sym_fluid: solo la nuvoletta fluida (colore simbolo)
    - divider_bar: barretta verticale (eredita colore testo)
    - letters: lettering TXT ENNOVA originale (+0.22 mm buffer)
    """
    s = wkt.loads(WKT_SYM_FLUID)
    d = wkt.loads(WKT_DIVIDER_BAR)
    l = wkt.loads(WKT_LETTERS)
    return s, d, l

def get_txt_letters_geometry(target_height=None):
    """Restituisce la geometria delle lettere TXT ENNOVA scalata all'altezza desiderata."""
    g = wkt.loads(WKT_LETTERS_ORIGIN)
    if target_height is not None:
        minx, miny, maxx, maxy = g.bounds
        h = maxy - miny
        if h > 1e-4:
            scale = target_height / h
            g = affinity.scale(g, xfact=scale, yfact=scale, origin=(0, 0))
    return g
